function validate([grid, k]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 50 || grid.length % 2 !== 0) return 'grid needs an even number of rows from 2 to 50.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 2 || n > 50 || n % 2 !== 0) return 'grid needs an even number of columns from 2 to 50.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 5000)) return 'Each cell is an integer from 1 to 5000.';
  }
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is an integer from 1 to 10^9.';
  return null;
}

