function rotateGrid(grid, k) {
  const m = grid.length;
  const n = grid[0].length;
  const result = grid.map(row => row.slice());
  for (let layer = 0; layer < Math.min(m, n) / 2; layer++) {
    const top = layer;
    const left = layer;
    const bottom = m - 1 - layer;
    const right = n - 1 - layer;
    const cells = [];
    for (let col = left; col < right; col++) {
      cells.push([top, col]);
    }
    for (let row = top; row < bottom; row++) {
      cells.push([row, right]);
    }
    for (let col = right; col > left; col--) {
      cells.push([bottom, col]);
    }
    for (let row = bottom; row > top; row--) {
      cells.push([row, left]);
    }
    const shift = k % cells.length;
    for (let i = 0; i < cells.length; i++) {
      const [fromRow, fromCol] = cells[(i + shift) % cells.length];
      const [toRow, toCol] = cells[i];
      result[toRow][toCol] = grid[fromRow][fromCol];
    }
  }
  return result;
}

