function rotateGrid(grid, k) {
  // Move every layer one step at a time, k mod (layer length) times.
  const g = grid.map(row => row.slice());
  const m = g.length, n = g[0].length;
  for (let t = 0; t < Math.min(m, n) / 2; t++) {
    const top = t, left = t, bottom = m - 1 - t, right = n - 1 - t;
    const length = 2 * (bottom - top + right - left);
    for (let step = 0; step < k % length; step++) {
      const saved = g[top][left];
      for (let c = left; c < right; c++) g[top][c] = g[top][c + 1];
      for (let r = top; r < bottom; r++) g[r][right] = g[r + 1][right];
      for (let c = right; c > left; c--) g[bottom][c] = g[bottom][c - 1];
      for (let r = bottom; r > top + 1; r--) g[r][left] = g[r - 1][left];
      g[top + 1][left] = saved;
    }
  }
  return g;
}

