function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 2 * (15 + Math.floor(rand() * 11)) : 2 * (1 + Math.floor(rand() * 3));
  const n = large ? 2 * (15 + Math.floor(rand() * 11)) : 2 * (1 + Math.floor(rand() * 3));
  const top = rand() < 0.3 ? 3 : 5000;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => 1 + Math.floor(rand() * top)));
  const k = large || rand() < 0.3 ? 1 + Math.floor(rand() * 1e9) : 1 + Math.floor(rand() * 40);
  return [grid, k];
}
